def repair_json_files():
    """
    Repairs corrupted JSON files by validating syntax and fixing issues.
    
    This function:
    1. Checks each JSON file for valid syntax
    2. If corrupted, attempts to fix common issues
    3. If unfixable, recreates the file with empty dict {} or empty list []
    4. Creates backup of corrupted files before repair
    
    Returns:
        dict: Statistics about the repair process
    """
    
    print("\n" + "="*70)
    print(f"  JSON FILE REPAIR UTILITY")
    print("="*70)
    print(f"  Start Time  : {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
    print("-"*70)
    
    # List of all JSON files to check
    json_files = [
        {"path": DEFAULT_ACCOUNTMANAGEMENT, "name": "DEFAULT_ACCOUNTMANAGEMENT", "default": {}},
        {"path": FETCHED_INVESTORS, "name": "FETCHED_INVESTORS", "default": {}},
        {"path": UPDATED_INVESTORS, "name": "UPDATED_INVESTORS", "default": {}},
        {"path": INVHARV_FETCHED_INVESTORS, "name": "INVHARV_FETCHED_INVESTORS", "default": {}},
        {"path": INVHARV_UPDATED_INVESTORS, "name": "INVHARV_UPDATED_INVESTORS", "default": {}},
        {"path": HARVHUB_FETCHED_INVESTORS, "name": "HARVHUB_FETCHED_INVESTORS", "default": {}},
        {"path": HARVHUB_UPDATED_INVESTORS, "name": "HARVHUB_UPDATED_INVESTORS", "default": {}},
        {"path": ALL_FETCHED_INVESTORS, "name": "ALL_FETCHED_INVESTORS", "default": {}},
        {"path": ALL_UPDATED_INVESTORS, "name": "ALL_UPDATED_INVESTORS", "default": {}}
    ]
    
    stats = {
        "processing_success": False,
        "total_files": len(json_files),
        "files_checked": 0,
        "files_valid": 0,
        "files_repaired": 0,
        "files_recreated": 0,
        "files_failed": 0,
        "repair_details": [],
        "errors": [],
        "timestamp": datetime.now().isoformat()
    }
    
    def get_backup_path(filepath):
        """Generate backup path with timestamp"""
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        dirname = os.path.dirname(filepath)
        basename = os.path.basename(filepath)
        name, ext = os.path.splitext(basename)
        backup_name = f"{name}_corrupted"
        return os.path.join(dirname, backup_name)
    
    def create_backup(filepath):
        """Create a backup of the corrupted file"""
        try:
            if os.path.exists(filepath):
                backup_path = get_backup_path(filepath)
                shutil.copy2(filepath, backup_path)
                return backup_path, True
        except Exception as e:
            print(f"   ⚠️ Could not create backup: {e}")
        return None, False
    
    def validate_and_repair_json(filepath, default_value, name):
        """
        Validate JSON file and repair if necessary.
        
        Returns:
            tuple: (is_valid, is_repaired, is_recreated, data, error_message)
        """
        # Check if file exists
        if not os.path.exists(filepath):
            print(f"   ⚠️ {name}: File not found, creating new...")
            try:
                # Ensure directory exists
                os.makedirs(os.path.dirname(filepath), exist_ok=True)
                # Create empty file
                with open(filepath, 'w', encoding='utf-8') as f:
                    json.dump(default_value, f, indent=2)
                return True, False, True, default_value, None
            except Exception as e:
                return False, False, False, None, f"Failed to create file: {e}"
        
        # Check if file is empty
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read().strip()
                
            if not content:
                print(f"   ⚠️ {name}: File is empty, recreating...")
                with open(filepath, 'w', encoding='utf-8') as f:
                    json.dump(default_value, f, indent=2)
                return True, False, True, default_value, None
        except Exception as e:
            print(f"   ⚠️ {name}: Could not read file: {e}")
        
        # Try to parse JSON
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                data = json.load(f)
            
            # If we got here, JSON is valid
            # Check if data type matches expected
            if isinstance(data, dict) and isinstance(default_value, dict):
                return True, False, False, data, None
            elif isinstance(data, list) and isinstance(default_value, list):
                return True, False, False, data, None
            else:
                # Data type mismatch - but still valid JSON
                print(f"   ⚠️ {name}: Data type mismatch (expected {type(default_value).__name__}, got {type(data).__name__})")
                # We'll recreate with correct type
                try:
                    # Create backup
                    backup_path, backup_created = create_backup(filepath)
                    if backup_created:
                        print(f"      📋 Backup created: {backup_path}")
                    
                    # Write correct type
                    with open(filepath, 'w', encoding='utf-8') as f:
                        json.dump(default_value, f, indent=2)
                    return True, True, True, default_value, "Data type mismatch fixed"
                except Exception as e:
                    return False, False, False, None, f"Failed to fix type mismatch: {e}"
                
        except json.JSONDecodeError as e:
            # JSON is corrupted - attempt to repair
            print(f"   ❌ {name}: JSON Decode Error: {e}")
            
            # Try to read file content
            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception as read_error:
                return False, False, False, None, f"Could not read file: {read_error}"
            
            # Attempt to repair common issues
            repaired_content = content
            
            # Fix 1: Remove BOM
            if repaired_content.startswith('\ufeff'):
                repaired_content = repaired_content[1:]
            
            # Fix 2: Fix single quotes to double quotes (JSON standard)
            # This is risky, so we'll be careful
            try:
                # Simple fix: replace single quotes with double quotes
                # But only if it's not already valid JSON
                import re
                
                # Fix 3: Remove trailing commas
                repaired_content = re.sub(r',\s*}', '}', repaired_content)
                repaired_content = re.sub(r',\s*]', ']', repaired_content)
                
                # Fix 4: Fix missing quotes around keys
                repaired_content = re.sub(r'([{,])\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*:', r'\1"\2":', repaired_content)
                
                # Try to parse repaired content
                try:
                    repaired_data = json.loads(repaired_content)
                    # Repair successful!
                    print(f"   🔧 {name}: Successfully repaired JSON")
                    
                    # Create backup before fixing
                    backup_path, backup_created = create_backup(filepath)
                    if backup_created:
                        print(f"      📋 Backup created: {backup_path}")
                    
                    # Write repaired content
                    with open(filepath, 'w', encoding='utf-8') as f:
                        json.dump(repaired_data, f, indent=2)
                    
                    return True, True, False, repaired_data, "JSON syntax repaired"
                    
                except json.JSONDecodeError:
                    # Repair failed, try more aggressive repair
                    pass
                
            except Exception as repair_error:
                print(f"   ⚠️ {name}: Repair attempt failed: {repair_error}")
            
            # If all repairs fail, recreate with default
            print(f"   🔄 {name}: Recreating file with default value")
            
            # Create backup
            backup_path, backup_created = create_backup(filepath)
            if backup_created:
                print(f"      📋 Backup created: {backup_path}")
            
            try:
                with open(filepath, 'w', encoding='utf-8') as f:
                    json.dump(default_value, f, indent=2)
                return True, False, True, default_value, "File recreated with default value"
            except Exception as write_error:
                return False, False, False, None, f"Failed to recreate file: {write_error}"
                
        except Exception as e:
            # Unexpected error
            return False, False, False, None, f"Unexpected error: {e}"
    
    # ============================================
    # PROCESS EACH FILE
    # ============================================
    
    print("\n🔍 Checking JSON files...")
    print("-"*70)
    
    for file_info in json_files:
        filepath = file_info["path"]
        name = file_info["name"]
        default_value = file_info["default"]
        
        print(f"\n📄 {name}:")
        print(f"   Path: {filepath}")
        
        stats["files_checked"] += 1
        
        is_valid, is_repaired, is_recreated, data, error_msg = validate_and_repair_json(
            filepath, default_value, name
        )
        
        detail = {
            "name": name,
            "path": filepath,
            "is_valid": is_valid,
            "is_repaired": is_repaired,
            "is_recreated": is_recreated,
            "error": error_msg
        }
        
        if is_valid:
            stats["files_valid"] += 1
            if is_repaired:
                stats["files_repaired"] += 1
                print(f"   ✅ {name}: REPAIRED")
                detail["status"] = "REPAIRED"
            elif is_recreated:
                stats["files_recreated"] += 1
                print(f"   ✅ {name}: RECREATED")
                detail["status"] = "RECREATED"
            else:
                print(f"   ✅ {name}: Valid")
                detail["status"] = "VALID"
            
            # Optionally, show data count for dict files
            if isinstance(data, dict):
                print(f"      Records: {len(data):,}")
            elif isinstance(data, list):
                print(f"      Items: {len(data):,}")
                
        else:
            stats["files_failed"] += 1
            print(f"   ❌ {name}: FAILED - {error_msg}")
            detail["status"] = "FAILED"
            stats["errors"].append(f"{name}: {error_msg}")
        
        stats["repair_details"].append(detail)
    
    # ============================================
    # SUMMARY
    # ============================================
    
    stats["processing_success"] = True if stats["files_failed"] == 0 else False
    
    print("\n" + "="*70)
    print(f"  REPAIR SUMMARY")
    print("="*70)
    
    print(f"\n  📊 Total files checked    : {stats['total_files']}")
    print(f"  ✅ Valid files            : {stats['files_valid']}")
    print(f"  🔧 Repaired files         : {stats['files_repaired']}")
    print(f"  🔄 Recreated files        : {stats['files_recreated']}")
    print(f"  ❌ Failed files           : {stats['files_failed']}")
    
    if stats["files_repaired"] > 0 or stats["files_recreated"] > 0:
        print(f"\n  📋 Files that were fixed:")
        for detail in stats["repair_details"]:
            if detail["status"] in ["REPAIRED", "RECREATED"]:
                print(f"     - {detail['name']}: {detail['status']}")
    
    if stats["errors"]:
        print(f"\n  ❌ Errors encountered ({len(stats['errors'])}):")
        for error in stats["errors"]:
            print(f"     - {error}")
    
    print(f"\n  ✅ Overall Status : {'SUCCESS' if stats['processing_success'] else 'WARNING - Some files failed'}")
    print(f"  🕐 Time           : {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
    print("="*70)
    
    return stats

def restore_missing_fields():
    """
    Heal missing fields across JSON files using hierarchical field-by-field merging.
    
    Priority order:
    1. INVHARV_UPDATED_INVESTORS and HARVHUB_UPDATED_INVESTORS (highest priority)
    2. INVHARV_FETCHED_INVESTORS and HARVHUB_FETCHED_INVESTORS
    3. ALL_UPDATED_INVESTORS
    4. ALL_FETCHED_INVESTORS (lowest priority)
    
    Rules:
    - Individual files (invharv/harvhub) ONLY heal their own users
    - ALL files can receive from individual files
    - Individual files can receive from ALL files if they're missing fields
    - Field-by-field merging (not whole record replacement)
    - Files heal each other if individual files are empty
    """
    
    print("\n" + "="*70)
    print(f"  HEALING MISSING FIELDS (FIELD-BY-FIELD MERGE)")
    print("="*70)
    print(f"  Start Time  : {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
    print("-"*70)
    
    def safe_read_json(file_path, default={}):
        """Safely read JSON file with error handling"""
        if not os.path.exists(file_path):
            print(f"    ⚠️ File not found: {file_path}")
            return default
        
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        except json.JSONDecodeError as e:
            print(f"    ❌ JSON decode error in {file_path}: {str(e)}")
            return default
        except PermissionError as e:
            print(f"    ⚠️ Permission denied reading {file_path}")
            return default
        except Exception as e:
            print(f"    ❌ Error reading {file_path}: {str(e)}")
            return default
    
    def safe_write_json(file_path, data):
        """Safely write JSON file with permission handling"""
        try:
            os.makedirs(os.path.dirname(file_path), exist_ok=True)
            with open(file_path, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
            return True
        except PermissionError as e:
            print(f"    ⚠️ Permission denied writing {file_path}")
            # Try to delete and retry
            try:
                if os.path.exists(file_path):
                    os.remove(file_path)
                    with open(file_path, 'w', encoding='utf-8') as f:
                        json.dump(data, f, indent=2, ensure_ascii=False)
                    return True
            except:
                pass
            return False
        except Exception as e:
            print(f"    ❌ Error writing {file_path}: {str(e)}")
            return False
    
    def merge_fields(source_record, target_record):
        """
        Merge fields from source to target where target is missing fields.
        Returns: (merged_record, fields_added)
        """
        if not source_record or not target_record:
            return target_record, 0
        
        merged = dict(target_record)  # Start with target
        fields_added = 0
        
        for key, value in source_record.items():
            # Skip 'id' field as it's the key
            if key == 'id':
                continue
            
            # Only add if target doesn't have this field OR target has it as None/null
            if key not in merged or merged[key] is None:
                merged[key] = value
                fields_added += 1
        
        return merged, fields_added
    
    def get_record_id(record):
        """Extract record ID from record dict"""
        if isinstance(record, dict):
            return str(record.get('id', ''))
        return None
    
    def merge_file_pair(source_data, target_data, source_name, target_name, skip_missing_ids=False):
        """
        Merge fields from source to target for matching IDs.
        If skip_missing_ids=True, only merge for IDs that exist in target.
        """
        if not source_data or not target_data:
            return target_data, 0, 0, 0
        
        merged_target = dict(target_data)
        total_records_healed = 0
        total_fields_added = 0
        total_records_skipped = 0
        
        for record_id, source_record in source_data.items():
            if record_id in merged_target:
                # Merge fields from source to target
                target_record = merged_target[record_id]
                merged_record, fields_added = merge_fields(source_record, target_record)
                
                if fields_added > 0:
                    merged_target[record_id] = merged_record
                    total_records_healed += 1
                    total_fields_added += fields_added
                    print(f"      ✅ Healed record {record_id}: added {fields_added} field(s)")
            else:
                if not skip_missing_ids:
                    # If target doesn't have this ID, add the whole record
                    merged_target[record_id] = source_record
                    total_records_healed += 1
                    print(f"      ➕ Added new record {record_id} from {source_name}")
                else:
                    total_records_skipped += 1
        
        return merged_target, total_records_healed, total_fields_added, total_records_skipped
    
    # Step 1: Load all JSON files
    print("\n📁 [1/4] Loading JSON Files...")
    
    invharv_fetched = safe_read_json(INVHARV_FETCHED_INVESTORS, {})
    invharv_updated = safe_read_json(INVHARV_UPDATED_INVESTORS, {})
    harvhub_fetched = safe_read_json(HARVHUB_FETCHED_INVESTORS, {})
    harvhub_updated = safe_read_json(HARVHUB_UPDATED_INVESTORS, {})
    all_fetched = safe_read_json(ALL_FETCHED_INVESTORS, {})
    all_updated = safe_read_json(ALL_UPDATED_INVESTORS, {})
    
    print(f"    📊 INVHARV_FETCHED: {len(invharv_fetched):,} records")
    print(f"    📊 INVHARV_UPDATED: {len(invharv_updated):,} records")
    print(f"    📊 HARVHUB_FETCHED: {len(harvhub_fetched):,} records")
    print(f"    📊 HARVHUB_UPDATED: {len(harvhub_updated):,} records")
    print(f"    📊 ALL_FETCHED: {len(all_fetched):,} records")
    print(f"    📊 ALL_UPDATED: {len(all_updated):,} records")
    
    # Step 2: Determine which individual files have data
    invharv_has_data = len(invharv_fetched) > 0 or len(invharv_updated) > 0
    harvhub_has_data = len(harvhub_fetched) > 0 or len(harvhub_updated) > 0
    
    print(f"\n📊 [2/4] Analyzing Data Sources...")
    print(f"    INVHARV has data: {invharv_has_data}")
    print(f"    HARVHUB has data: {harvhub_has_data}")
    
    all_fetched_modified = False
    all_updated_modified = False
    invharv_fetched_modified = False
    invharv_updated_modified = False
    harvhub_fetched_modified = False
    harvhub_updated_modified = False
    
    total_fields_added_all_fetched = 0
    total_fields_added_all_updated = 0
    total_fields_added_invharv_fetched = 0
    total_fields_added_invharv_updated = 0
    total_fields_added_harvhub_fetched = 0
    total_fields_added_harvhub_updated = 0
    
    print("\n🔧 [3/4] Healing Files...")
    print("-"*70)
    
    # CASE 1: Individual files have data - heal ALL files from individual files
    if invharv_has_data or harvhub_has_data:
        print("\n  📋 Using INDIVIDUAL files as primary source...")
        
        # 1A: Heal ALL_UPDATED from INVHARV_UPDATED
        if invharv_updated:
            print("\n    🔄 INVHARV_UPDATED → ALL_UPDATED")
            all_updated, healed, fields, skipped = merge_file_pair(
                invharv_updated, all_updated, "INVHARV_UPDATED", "ALL_UPDATED", skip_missing_ids=True
            )
            if healed > 0:
                all_updated_modified = True
                total_fields_added_all_updated += fields
                print(f"      ✅ Healed {healed} records, added {fields} fields")
            else:
                print(f"      ℹ️ No healing needed")
        
        # 1B: Heal ALL_UPDATED from HARVHUB_UPDATED
        if harvhub_updated:
            print("\n    🔄 HARVHUB_UPDATED → ALL_UPDATED")
            all_updated, healed, fields, skipped = merge_file_pair(
                harvhub_updated, all_updated, "HARVHUB_UPDATED", "ALL_UPDATED", skip_missing_ids=True
            )
            if healed > 0:
                all_updated_modified = True
                total_fields_added_all_updated += fields
                print(f"      ✅ Healed {healed} records, added {fields} fields")
            else:
                print(f"      ℹ️ No healing needed")
        
        # 1C: Heal ALL_FETCHED from INVHARV_FETCHED
        if invharv_fetched:
            print("\n    🔄 INVHARV_FETCHED → ALL_FETCHED")
            all_fetched, healed, fields, skipped = merge_file_pair(
                invharv_fetched, all_fetched, "INVHARV_FETCHED", "ALL_FETCHED", skip_missing_ids=True
            )
